"""Strict read-only evaluator for Android OpenTwitter workflows."""

from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Mapping
from urllib.request import urlopen

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus
from evaluators.cua_review.platforms.android.openshop_support import (
    OpenShopAndroidStore,
    _devtools_runtime_evaluate,
    _free_tcp_port,
)
from evaluators.cua_review.platforms.android.opentwitter_support import stated_order_check



def event_sequence(value: Any) -> int:
    """Return an event's sequence number, or `0` when it carries none.

    A stored sequence is normally a number; a document that carries something
    else is not a reason to abandon the judgement, so the value is treated as
    absent instead.
    """
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0

class OpenTwitterWorkflowEvaluator(BaseEvaluator):
    """Verify exact final state plus attributable OpenTwitter event evidence."""

    BASELINE_FILENAME = "opentwitter_baseline.json"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        params = dict(context.get("params") or {})
        run_dir_raw = context.get("run_dir")
        if controller is None or not hasattr(controller, "execute_adb"):
            return EvalResult(
                status=EvalStatus.ERROR,
                message="runner-provided controller.execute_adb is required",
                metadata={"read_only": True},
            )

        app_package = str(params.get("app_package") or "com.killt.opentwitter").strip()
        local_state_key = str(params.get("local_state_key") or "opentwitter.localState.v7").strip()
        expected_handle = str(params.get("expected_handle") or "alex").strip()
        created_after = str(params.get("created_after") or "").strip()
        target_posts = params.get("target_posts") if isinstance(params.get("target_posts"), list) else []
        expected_posts = params.get("created_posts") if isinstance(params.get("created_posts"), list) else []
        expected_messages = params.get("messages") if isinstance(params.get("messages"), list) else []

        try:
            state = OpenShopAndroidStore(
                controller,
                app_package=app_package,
                local_state_key=local_state_key,
            ).read_state_read_only()
            dom = self._read_dom_state(controller, app_package)
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Read-only OpenTwitter state query failed: {type(exc).__name__}: {exc}",
                metadata={
                    "read_only": True,
                    "app_package": app_package,
                    "local_state_key": local_state_key,
                    "exception_type": type(exc).__name__,
                },
            )

        checks: list[dict[str, Any]] = []
        failures: list[str] = []

        def add_check(name: str, passed: bool, expected: Any, observed: Any, **evidence: Any) -> None:
            record = {
                "name": name,
                "passed": bool(passed),
                "expected": expected,
                "observed": observed,
                **evidence,
            }
            checks.append(record)
            if not passed:
                failures.append(name)

        baseline: dict[str, Any] | None = None
        if run_dir_raw:
            baseline_path = Path(str(run_dir_raw)) / self.BASELINE_FILENAME
            if baseline_path.exists():
                try:
                    loaded = json.loads(baseline_path.read_text(encoding="utf-8"))
                    baseline = loaded if isinstance(loaded, dict) else None
                except Exception:
                    baseline = None
            # A run directory may carry a recorded baseline, whose events are
            # then excluded from the causal suffix.  Its absence is recorded for
            # a reader and changes nothing about the verdict: the criteria are
            # about the state the task asks for, and that state is read either
            # way.
            baseline_reference = str(baseline_path)
        else:
            baseline_reference = None

        baseline_seq = event_sequence((baseline or {}).get("evaluation_event_seq"))
        all_events = state.get("evaluationEvents") if isinstance(state.get("evaluationEvents"), list) else []
        events = [
            event
            for event in all_events
            if isinstance(event, Mapping) and event_sequence(event.get("seq")) > baseline_seq
        ]
        if baseline is not None:
            add_check(
                "baseline_snapshot_exact",
                str(baseline.get("snapshot_name") or "") == str(params.get("snapshot_name") or ""),
                str(params.get("snapshot_name") or ""),
                str(baseline.get("snapshot_name") or ""),
            )
            add_check(
                "baseline_was_clean",
                not bool(baseline.get("polluted_target_evidence")),
                [],
                baseline.get("polluted_target_evidence"),
            )

        session = state.get("session") if isinstance(state.get("session"), Mapping) else {}
        user = session.get("user") if isinstance(session.get("user"), Mapping) else {}
        observed_handle = str(user.get("handle") or "")
        add_check("session_logged_in", bool(session.get("loggedIn")), True, bool(session.get("loggedIn")))
        add_check("session_handle_exact", observed_handle == expected_handle, expected_handle, observed_handle)

        user_states = state.get("userStateByHandle") if isinstance(state.get("userStateByHandle"), Mapping) else {}
        social = user_states.get(expected_handle) if isinstance(user_states.get(expected_handle), Mapping) else {}
        liked = {str(value) for value in (social.get("likedPostIds") or [])}
        reposted = {str(value) for value in (social.get("repostedPostIds") or [])}
        bookmarked = {str(value) for value in (social.get("bookmarkedPostIds") or [])}
        messages = social.get("messages") if isinstance(social.get("messages"), list) else []
        notifications = social.get("notifications") if isinstance(social.get("notifications"), list) else []
        posts = state.get("posts") if isinstance(state.get("posts"), list) else []
        comments = state.get("comments") if isinstance(state.get("comments"), Mapping) else {}

        matched_ids: dict[str, str] = {}
        # Business objects the instruction orders, by label (see stated_order_check).
        order_anchors: dict[str, dict[str, Any] | None] = {}
        for spec in target_posts:
            if not isinstance(spec, Mapping):
                continue
            post_id = str(spec.get("id") or "")
            matches = [post for post in posts if isinstance(post, Mapping) and str(post.get("id") or "") == post_id]
            post = matches[0] if len(matches) == 1 else {}
            identity_ok = (
                len(matches) == 1
                and str(post.get("authorHandle") or "") == str(spec.get("author_handle") or "")
                and str(post.get("text") or "") == str(spec.get("text") or "")
            )
            add_check(
                f"target_post_{post_id}_identity",
                identity_ok,
                {"id": post_id, "author_handle": spec.get("author_handle"), "text": spec.get("text")},
                {"match_count": len(matches), "author_handle": post.get("authorHandle"), "text": post.get("text")},
                matched_object_id=post_id if identity_ok else None,
            )
            action_sets = {"like": liked, "repost": reposted, "bookmark": bookmarked}
            for action in spec.get("actions") or []:
                active = post_id in action_sets.get(str(action), set())
                add_check(
                    f"target_post_{post_id}_{action}_active",
                    active,
                    True,
                    active,
                    matched_object_id=post_id,
                )
            reply_text = str(spec.get("reply_text") or "")
            if reply_text:
                reply_matches = [
                    item
                    for item in (comments.get(post_id) or [])
                    if isinstance(item, Mapping)
                    and str(item.get("authorHandle") or "") == expected_handle
                    and str(item.get("text") or "") == reply_text
                    and self._created_after(item.get("createdAt"), created_after)
                ]
                add_check(
                    f"target_post_{post_id}_reply_exact_unique",
                    len(reply_matches) == 1,
                    {"author_handle": expected_handle, "text": reply_text, "count": 1, "created_after": created_after},
                    {"count": len(reply_matches), "ids": [item.get("id") for item in reply_matches]},
                    matched_object_id=reply_matches[0].get("id") if len(reply_matches) == 1 else None,
                )

        for spec in expected_messages:
            if not isinstance(spec, Mapping):
                continue
            handle = str(spec.get("handle") or "")
            text = str(spec.get("text") or "")
            matches = [
                item
                for item in messages
                if isinstance(item, Mapping)
                and bool(item.get("outbound"))
                and str(item.get("handle") or "") == handle
                and str(item.get("text") or "") == text
                and self._created_after(item.get("createdAt"), created_after)
            ]
            add_check(
                f"message_{handle}_exact_unique",
                len(matches) == 1,
                {"handle": handle, "text": text, "outbound": True, "count": 1},
                {"count": len(matches), "ids": [item.get("id") for item in matches]},
                matched_object_id=matches[0].get("id") if len(matches) == 1 else None,
            )
            order_anchors[f"message:{handle}"] = (
                {"at": matches[0].get("createdAt"), "id": matches[0].get("id")} if len(matches) == 1 else None
            )

        created_post_objects: dict[str, Mapping[str, Any]] = {}
        for spec in expected_posts:
            if not isinstance(spec, Mapping):
                continue
            text = str(spec.get("text") or "")
            matches = [
                post
                for post in posts
                if isinstance(post, Mapping)
                and str(post.get("authorHandle") or "") == expected_handle
                and str(post.get("text") or "") == text
                and self._created_after(post.get("createdAt"), created_after)
            ]
            add_check(
                f"created_post_{text}_exact_unique",
                len(matches) == 1,
                {"author_handle": expected_handle, "text": text, "count": 1},
                {"count": len(matches), "ids": [post.get("id") for post in matches]},
                matched_object_id=matches[0].get("id") if len(matches) == 1 else None,
            )
            if len(matches) == 1:
                created_post_objects[text] = matches[0]
                matched_ids[text] = str(matches[0].get("id") or "")
            order_anchors[f"post:{text}"] = (
                {"at": matches[0].get("createdAt"), "id": matches[0].get("id")} if len(matches) == 1 else None
            )

        owner_text = str(params.get("owner_post_text") or "Owners aligned.")
        owner_post = created_post_objects.get(owner_text)
        owner_post_id = str(owner_post.get("id") or "") if isinstance(owner_post, Mapping) else ""
        add_check(
            "owners_post_bookmarked",
            bool(owner_post_id) and owner_post_id in bookmarked,
            True,
            bool(owner_post_id) and owner_post_id in bookmarked,
            matched_object_id=owner_post_id or None,
        )
        owner_reply = str(params.get("owner_reply_text") or "Next steps assigned")
        owner_reply_matches = [
            item
            for item in (comments.get(owner_post_id) or [])
            if isinstance(item, Mapping)
            and str(item.get("authorHandle") or "") == expected_handle
            and str(item.get("text") or "") == owner_reply
            and self._created_after(item.get("createdAt"), created_after)
        ] if owner_post_id else []
        add_check(
            "owners_post_reply_exact_unique",
            len(owner_reply_matches) == 1,
            {"post_id": owner_post_id, "text": owner_reply, "count": 1},
            {"count": len(owner_reply_matches), "ids": [item.get("id") for item in owner_reply_matches]},
            matched_object_id=owner_reply_matches[0].get("id") if len(owner_reply_matches) == 1 else None,
        )

        unread_ids = [str(item.get("id") or "") for item in notifications if isinstance(item, Mapping) and not bool(item.get("read"))]
        add_check("all_notifications_read", len(unread_ids) == 0 and len(notifications) > 0, 0, len(unread_ids), unread_ids=unread_ids)

        # Only the orders the English instruction states are judged ("direct
        # messages must be sent in the following order", "two new posts ... in
        # sequence: first ..., then ..."), from the created objects' own times.
        # The rest of the run's order is free: browsing, the trends visited and
        # the order of the other actions are not graded.
        if params.get("stated_order"):
            order_ok, order_expected, order_observed = stated_order_check(params.get("stated_order"), order_anchors)
            add_check("instruction_stated_order", order_ok, order_expected, order_observed)

        final_observation = context.get("final_observation")
        foreground = str(getattr(final_observation, "foreground_bundle_id", "") or "")
        foreground_source = "final_observation"
        foreground_system_evidence = ""
        if not foreground:
            try:
                window_dump = str(controller.execute_adb(["shell", "dumpsys", "window", "windows"]) or "")
                activity_dump = str(
                    controller.execute_adb(["shell", "dumpsys", "activity", "activities"]) or ""
                )
                focus_lines = [
                    line.strip()
                    for line in (window_dump + "\n" + activity_dump).splitlines()
                    if any(
                        marker in line
                        for marker in (
                            "mCurrentFocus",
                            "mFocusedApp",
                            "topResumedActivity",
                            "ResumedActivity",
                        )
                    )
                ]
                foreground_system_evidence = "\n".join(focus_lines[:8])
                if app_package in foreground_system_evidence:
                    foreground = app_package
                    foreground_source = "read_only_dumpsys_window_activity"
            except Exception as exc:
                foreground_system_evidence = f"{type(exc).__name__}: {exc}"
        add_check(
            "final_foreground_app",
            foreground == app_package,
            app_package,
            foreground,
            evidence_source=foreground_source,
            system_evidence=foreground_system_evidence,
        )
        add_check("final_view_home", str(dom.get("view") or "") == "home", "home", dom.get("view"))
        body_text = str(dom.get("body_text") or "")
        add_check("final_owners_post_visible", owner_text in body_text, owner_text, owner_text if owner_text in body_text else "<not visible>")

        metadata = {
            "read_only": True,
            "app_package": app_package,
            "local_state_key": local_state_key,
            "created_after": created_after,
            "baseline_used": baseline is not None,
            "baseline_event_seq": baseline_seq,
            "matched_object_ids": matched_ids,
            "checks": checks,
            "failures": failures,
            "final_dom": {"view": dom.get("view"), "body_contains_owners_post": owner_text in body_text},
        }
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenTwitter final state is incomplete or not attributable to the required workflow",
                metadata=metadata,
            )
        return EvalResult(
            status=EvalStatus.PASS,
            message="OpenTwitter exact final state and the instruction's stated orders match the task",
            metadata=metadata,
        )

    @staticmethod
    def _created_after(raw: Any, threshold: str) -> bool:
        if not threshold:
            return bool(str(raw or "").strip())
        try:
            observed = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
            expected = datetime.fromisoformat(threshold.replace("Z", "+00:00"))
            if observed.tzinfo is None:
                observed = observed.replace(tzinfo=timezone.utc)
            if expected.tzinfo is None:
                expected = expected.replace(tzinfo=timezone.utc)
            return observed >= expected
        except (TypeError, ValueError):
            return False

    @staticmethod
    def _read_dom_state(controller: Any, app_package: str) -> dict[str, Any]:
        pid = str(controller.execute_adb(["shell", "pidof", app_package]) or "").strip().split()
        if not pid:
            raise RuntimeError(f"OpenTwitter process is not running: {app_package}")
        port = _free_tcp_port()
        forward_spec = f"tcp:{port}"
        controller.execute_adb(["forward", forward_spec, f"localabstract:webview_devtools_remote_{pid[0]}"])
        try:
            with urlopen(f"http://127.0.0.1:{port}/json", timeout=4.0) as response:
                targets = json.loads(response.read().decode("utf-8"))
            target = next(
                item
                for item in targets
                if isinstance(item, Mapping) and str(item.get("webSocketDebuggerUrl") or "").strip()
            )
            expression = (
                "JSON.stringify({"
                "view:(typeof appState==='object'&&appState?String(appState.view||''):''),"
                "body_text:String(document.body&&document.body.innerText||'')"
                "})"
            )
            raw = _devtools_runtime_evaluate(str(target["webSocketDebuggerUrl"]), expression)
            payload = json.loads(str(raw or "{}"))
            return payload if isinstance(payload, dict) else {}
        finally:
            controller.execute_adb(["forward", "--remove", forward_spec])
